package cli

import (
	"encoding/base64"
	"fmt"
	"os"
	"strings"
)

// supportsKittyGraphics checks if current terminal is Kitty, Ghostty, or WezTerm
func supportsKittyGraphics() bool {
	term := os.Getenv("TERM")
	termProg := os.Getenv("TERM_PROGRAM")
	return strings.Contains(term, "kitty") ||
		strings.EqualFold(termProg, "ghostty") ||
		strings.EqualFold(termProg, "WezTerm") ||
		os.Getenv("KITTY_WINDOW_ID") != "" ||
		os.Getenv("GHOSTTY_RESOURCES_DIR") != "" ||
		os.Getenv("WEZTERM_PANE") != ""
}

// renderKittyImage renders the native high-resolution PNG using the Kitty graphics protocol
func renderKittyImage(path string, cols, rows int) bool {
	data, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	encoded := base64.StdEncoding.EncodeToString(data)

	chunkSize := 4096
	for i := 0; i < len(encoded); i += chunkSize {
		end := i + chunkSize
		if end > len(encoded) {
			end = len(encoded)
		}
		chunk := encoded[i:end]
		if i == 0 {
			more := 1
			if end == len(encoded) {
				more = 0
			}
			fmt.Printf("\033_Ga=T,f=100,c=%d,r=%d,m=%d;%s\033\\", cols, rows, more, chunk)
		} else if end == len(encoded) {
			fmt.Printf("\033_Gm=0;%s\033\\", chunk)
		} else {
			fmt.Printf("\033_Gm=1;%s\033\\", chunk)
		}
	}
	fmt.Println()
	return true
}

