// PrintBanner renders just the mascot banner
func PrintBanner(modelName string) {
	fmt.Println()

	// 1. Try native GPU image protocol (Kitty / Ghostty / WezTerm)
	if supportsKittyGraphics() {
		if renderKittyImage("public/mascot.png", 24, 11) {
			fmt.Println()
			return
		}
	}

	// 2. Fallback: print the crisp ANSI mascot
	for _, line := range ghostSprite {
		fmt.Printf("  %s\n", line)
	}
	fmt.Println()
}
